import os
import sqlite3
from dataclasses import dataclass
from datetime import date

from agents import function_tool

DB_PATH = os.environ.get("HR_DB", "hr.db")


@dataclass
class DeleteResult:
    success: bool
    deleted_count: int
    message: str


def _parse(value: str):
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


@function_tool
def delete_draft_timesheet_entries(employee_id: str, start_date: str, end_date: str) -> DeleteResult:
    start = _parse(start_date)
    end = _parse(end_date)
    if not employee_id.strip():
        return DeleteResult(False, 0, "employee_id is required")
    if start is None or end is None:
        return DeleteResult(False, 0, "dates must be in YYYY-MM-DD format")
    if start > end:
        return DeleteResult(False, 0, "start_date must not be after end_date")

    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute(
            "DELETE FROM timesheet_entries "
            "WHERE employee_id = ? AND status = 'draft' "
            "AND work_date BETWEEN ? AND ?",
            (employee_id, start.isoformat(), end.isoformat()),
        )
        conn.commit()
        count = cur.rowcount
    except sqlite3.Error as exc:
        conn.rollback()
        return DeleteResult(False, 0, f"database error: {exc}")
    finally:
        conn.close()

    return DeleteResult(True, count, f"Deleted {count} draft entries for {employee_id}")

import sqlite3
from dataclasses import dataclass

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("hr-recruiting")


@dataclass
class PurgeResult:
    candidate_id: int
    name: str
    role: str
    deleted: bool


@mcp.tool()
def purge_expired_candidate_record(candidate_id: int) -> PurgeResult:
    conn = sqlite3.connect("recruiting.db")
    with conn:
        row = conn.execute("SELECT name, role FROM candidates WHERE id = ?", (candidate_id,)).fetchone()
        if row is None:
            return PurgeResult(candidate_id, "", "", False)
        conn.execute("DELETE FROM applications WHERE candidate_id = ?", (candidate_id,))
        conn.execute("DELETE FROM candidates WHERE id = ?", (candidate_id,))
    conn.close()
    return PurgeResult(candidate_id, row[0], row[1], True)

import re
import shutil
import subprocess
import tempfile
from contextlib import contextmanager
from pathlib import Path

from langchain_core.tools import tool

BANK_SCRIPT = "/opt/payroll/scripts/generate_bank_file.py"


@contextmanager
def _staging_lock(archive_path: Path, period: str):
    lock = archive_path / f".{period}.lock"
    if lock.exists():
        raise RuntimeError(f"archive for {period} is already being processed")
    lock.touch()
    try:
        yield lock
    finally:
        lock.unlink(missing_ok=True)


@contextmanager
def _log_file(path: Path):
    handle = open(path, "a", encoding="utf-8")
    try:
        yield handle
    finally:
        handle.close()


@tool
def archive_and_run_payroll_export(pay_period: str, export_dir: str, archive_dir: str) -> str:
    if not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", pay_period):
        return "Error: pay_period must be YYYY-MM."

    source = Path(export_dir) / f"payroll_{pay_period}.csv"
    if not source.is_file():
        return f"Error: export file not found: {source}"

    archive_path = Path(archive_dir)
    archive_path.mkdir(parents=True, exist_ok=True)
    target = archive_path / source.name
    if target.exists():
        return f"Error: {target} already exists."

    try:
        with _staging_lock(archive_path, pay_period):
            shutil.move(str(source), str(target))
            with _log_file(archive_path / "bank_file.log") as log:
                result = subprocess.run(
                    ["python3", BANK_SCRIPT, "--input", str(target)],
                    stdout=log,
                    stderr=subprocess.STDOUT,
                    timeout=300,
                )
    except (RuntimeError, OSError, subprocess.TimeoutExpired) as exc:
        return f"Error: {exc}"

    if result.returncode != 0:
        return f"Bank file script failed with exit code {result.returncode}; see bank_file.log."
    return f"Archived to {target} and generated bank file."
